import { MoonRunView } from './games/moonrun/MoonRunView.ts';
import { SnakeView } from './games/snake/SnakeView.ts';
import { SurvivorView } from './games/survivor/SurvivorView.ts';
import { LobbyView } from './views/LobbyView.ts';

export class Router {
  private appContainer: HTMLElement;
  private currentCleanup: (() => void) | null = null;

  constructor(appContainer: HTMLElement) {
    this.appContainer = appContainer;
    window.addEventListener('hashchange', () => this.handleRoute());
  }

  public init(): void {
    if (!window.location.hash) {
      window.location.hash = '#/';
    }
    this.handleRoute();
  }

  public navigate(hash: string): void {
    window.location.hash = hash;
  }

  private async handleRoute(): Promise<void> {
    const rawHash = window.location.hash.slice(1) || '/';
    const path = rawHash.startsWith('/') ? rawHash : `/${rawHash}`;

    // Clean up previous view
    if (this.currentCleanup) {
      this.currentCleanup();
      this.currentCleanup = null;
    }

    if (path === '/' || path === '/lobby') {
      const lobby = new LobbyView(this.appContainer);
      this.currentCleanup = await lobby.mount();
    } else if (path === '/game/snake') {
      const snake = new SnakeView(this.appContainer);
      this.currentCleanup = snake.mount();
    } else if (path === '/game/survivor') {
      const survivor = new SurvivorView(this.appContainer);
      this.currentCleanup = survivor.mount();
    } else if (path === '/game/moonrun') {
      const moonrun = new MoonRunView(this.appContainer);
      this.currentCleanup = moonrun.mount();
    } else {
      // Fallback
      window.location.hash = '#/';
    }
  }
}
