import { GameScoreRecord } from '../types.ts';
import { StorageAdapter } from './StorageAdapter.ts';

const HIGH_SCORE_KEY = 'snek_arcade_high_score';
const HISTORY_KEY = 'snek_arcade_history';

export class LocalStorageAdapter implements StorageAdapter {
  async getHighScore(): Promise<number> {
    const raw = localStorage.getItem(HIGH_SCORE_KEY);
    if (!raw) return 0;
    const parsed = parseInt(raw, 10);
    return isNaN(parsed) ? 0 : parsed;
  }

  async saveScore(record: GameScoreRecord): Promise<{ isNewHighScore: boolean }> {
    const currentHigh = await this.getHighScore();
    const isNewHighScore = record.score > currentHigh;

    if (isNewHighScore) {
      localStorage.setItem(HIGH_SCORE_KEY, String(record.score));
    }

    try {
      const historyRaw = localStorage.getItem(HISTORY_KEY);
      const history: GameScoreRecord[] = historyRaw ? JSON.parse(historyRaw) : [];
      history.unshift(record);
      // Keep last 20 records
      const trimmed = history.slice(0, 20);
      localStorage.setItem(HISTORY_KEY, JSON.stringify(trimmed));
    } catch {
      // Ignore quota errors
    }

    return { isNewHighScore };
  }

  async getRecentScores(limit = 10): Promise<GameScoreRecord[]> {
    try {
      const historyRaw = localStorage.getItem(HISTORY_KEY);
      if (!historyRaw) return [];
      const history: GameScoreRecord[] = JSON.parse(historyRaw);
      return history.slice(0, limit);
    } catch {
      return [];
    }
  }
}
