import { SoundManager } from '../../audio/SoundManager.ts';
import { ParticleSystem } from '../../engine/ParticleSystem.ts';

export interface Enemy {
  id: string;
  x: number;
  y: number;
  hp: number;
  maxHp: number;
  speed: number;
  size: number;
  type: 'BEAR' | 'RED_CANDLE';
  color: string;
}

export interface Projectile {
  x: number;
  y: number;
  vx: number;
  vy: number;
  damage: number;
  life: number;
}

export interface ExpGem {
  id: string;
  x: number;
  y: number;
  value: number;
}

export interface SurvivorCallbacks {
  onHpChange: (hp: number, maxHp: number) => void;
  onExpChange: (exp: number, nextExp: number, level: number) => void;
  onKillsChange: (kills: number) => void;
  onTimerChange: (seconds: number) => void;
  onLevelUp: (choices: UpgradeChoice[]) => void;
  onGameOver: (kills: number, timeSec: number, level: number) => void;
}

export interface UpgradeChoice {
  id: string;
  title: string;
  desc: string;
  category: 'WEAPON' | 'STATS' | 'SPECIAL';
}

export class SurvivorEngine {
  public canvas: HTMLCanvasElement;
  public ctx: CanvasRenderingContext2D;
  private callbacks: SurvivorCallbacks;
  public soundManager: SoundManager;
  public particleSystem: ParticleSystem;

  // Arena Dimensions
  public width: number = 440;
  public height: number = 440;

  // Player
  public px: number = 220;
  public py: number = 220;
  public pvx: number = 0;
  public pvy: number = 0;
  public hp: number = 100;
  public maxHp: number = 100;
  public speed: number = 2.4;
  public playerSize: number = 18;

  // Stats & Progression
  public level: number = 1;
  public exp: number = 0;
  public nextExp: number = 5;
  public kills: number = 0;
  public elapsedTime: number = 0;

  // Weapon Stats
  public venomCount: number = 1;
  public venomCooldown: number = 420;
  private venomTimer: number = 0;
  public orbitCount: number = 1;
  public orbitSpeed: number = 0.05;
  private orbitAngle: number = 0;

  // Game Entities
  public enemies: Enemy[] = [];
  public projectiles: Projectile[] = [];
  public expGems: ExpGem[] = [];

  // State
  public isRunning: boolean = false;
  public isPaused: boolean = false;
  private lastTime: number = 0;
  private spawnTimer: number = 0;
  private animFrameId: number | null = null;
  private invulnerableTimer: number = 0;

  // Head sprite
  private headImage: HTMLImageElement = new Image();
  private imageLoaded: boolean = false;

  constructor(canvas: HTMLCanvasElement, callbacks: SurvivorCallbacks) {
    this.canvas = canvas;
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('No 2D context');
    this.ctx = ctx;
    this.callbacks = callbacks;
    this.soundManager = new SoundManager();
    this.particleSystem = new ParticleSystem();

    this.headImage.src = './assets/face/SNEK_0004.webp';
    this.headImage.onload = () => {
      this.imageLoaded = true;
    };

    this.initCanvasSize();
  }

  private initCanvasSize(): void {
    const dpr = window.devicePixelRatio || 1;
    this.canvas.width = this.width * dpr;
    this.canvas.height = this.height * dpr;
    this.ctx.scale(dpr, dpr);
  }

  public start(): void {
    this.soundManager.unlock();
    this.px = this.width / 2;
    this.py = this.height / 2;
    this.pvx = 0;
    this.pvy = 0;
    this.hp = 100;
    this.maxHp = 100;
    this.speed = 2.4;
    this.level = 1;
    this.exp = 0;
    this.nextExp = 5;
    this.kills = 0;
    this.elapsedTime = 0;

    this.venomCount = 1;
    this.orbitCount = 1;
    this.enemies = [];
    this.projectiles = [];
    this.expGems = [];
    this.particleSystem.clear();

    this.isRunning = true;
    this.isPaused = false;
    this.lastTime = performance.now();

    this.callbacks.onHpChange(this.hp, this.maxHp);
    this.callbacks.onExpChange(this.exp, this.nextExp, this.level);
    this.callbacks.onKillsChange(this.kills);
    this.callbacks.onTimerChange(0);

    this.loop(this.lastTime);
  }

  public pause(): void {
    this.isPaused = true;
  }

  public resume(): void {
    this.isPaused = false;
    this.lastTime = performance.now();
  }

  public setMoveVector(vx: number, vy: number): void {
    this.pvx = vx;
    this.pvy = vy;
  }

  public applyUpgrade(upgradeId: string): void {
    switch (upgradeId) {
      case 'MULTI_VENOM':
        this.venomCount = Math.min(4, this.venomCount + 1);
        break;
      case 'BURN_AURA':
        this.orbitCount = Math.min(4, this.orbitCount + 1);
        this.orbitSpeed += 0.015;
        break;
      case 'SLITHER_SPEED':
        this.speed *= 1.2;
        break;
      case 'DIAMOND_HANDS':
        this.maxHp += 25;
        this.hp = this.maxHp;
        this.callbacks.onHpChange(this.hp, this.maxHp);
        break;
      case 'MEGA_BURN':
        // Kill all enemies currently alive
        for (const e of this.enemies) {
          this.particleSystem.emitDeath(e.x, e.y);
          this.expGems.push({ id: `gem_${Math.random()}`, x: e.x, y: e.y, value: 1 });
        }
        this.kills += this.enemies.length;
        this.enemies = [];
        this.callbacks.onKillsChange(this.kills);
        break;
    }
    this.resume();
  }

  private loop = (timestamp: number): void => {
    if (!this.isRunning) return;

    const dt = timestamp - this.lastTime;
    this.lastTime = timestamp;

    if (!this.isPaused) {
      this.update(dt);
    }
    this.render();

    this.animFrameId = requestAnimationFrame(this.loop);
  };

  public destroy(): void {
    this.isRunning = false;
    if (this.animFrameId !== null) {
      cancelAnimationFrame(this.animFrameId);
    }
  }

  private update(dt: number): void {
    this.elapsedTime += dt / 1000;
    this.callbacks.onTimerChange(Math.floor(this.elapsedTime));
    this.particleSystem.update(dt);

    if (this.invulnerableTimer > 0) {
      this.invulnerableTimer -= dt;
    }

    // 1. Move Player
    this.px = Math.max(this.playerSize, Math.min(this.width - this.playerSize, this.px + this.pvx * this.speed));
    this.py = Math.max(this.playerSize, Math.min(this.height - this.playerSize, this.py + this.pvy * this.speed));

    // 2. Spawn Enemies
    this.spawnTimer += dt;
    const spawnInterval = Math.max(500, 1500 - this.elapsedTime * 15);
    if (this.spawnTimer >= spawnInterval) {
      this.spawnTimer = 0;
      this.spawnEnemy();
    }

    // 3. Move Enemies towards Player
    for (let i = this.enemies.length - 1; i >= 0; i--) {
      const e = this.enemies[i];
      const dx = this.px - e.x;
      const dy = this.py - e.y;
      const dist = Math.hypot(dx, dy);

      if (dist > 0) {
        e.x += (dx / dist) * e.speed;
        e.y += (dy / dist) * e.speed;
      }

      // Check collision with Player
      if (dist < this.playerSize + e.size && this.invulnerableTimer <= 0) {
        this.hp -= 12;
        this.invulnerableTimer = 600; // 0.6s grace
        this.soundManager.playDie();
        this.callbacks.onHpChange(Math.max(0, this.hp), this.maxHp);

        if (this.hp <= 0) {
          this.handleGameOver();
          return;
        }
      }
    }

    // 4. Auto Fire Venom Shot
    this.venomTimer += dt;
    if (this.venomTimer >= this.venomCooldown && this.enemies.length > 0) {
      this.venomTimer = 0;
      this.fireVenom();
    }

    // 5. Update Projectiles
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.life -= dt;

      let hit = false;
      for (let j = this.enemies.length - 1; j >= 0; j--) {
        const e = this.enemies[j];
        if (Math.hypot(p.x - e.x, p.y - e.y) < e.size + 4) {
          e.hp -= p.damage;
          this.particleSystem.emitEat(p.x, p.y);
          hit = true;

          if (e.hp <= 0) {
            this.killEnemy(j);
          }
          break;
        }
      }

      if (hit || p.life <= 0) {
        this.projectiles.splice(i, 1);
      }
    }

    // 6. Update Orbit Burn Shield
    this.orbitAngle += this.orbitSpeed;
    const orbitRadius = 45;
    for (let o = 0; o < this.orbitCount; o++) {
      const angle = this.orbitAngle + (o * Math.PI * 2) / this.orbitCount;
      const ox = this.px + Math.cos(angle) * orbitRadius;
      const oy = this.py + Math.sin(angle) * orbitRadius;

      // Orbit damage to colliding enemies
      for (let j = this.enemies.length - 1; j >= 0; j--) {
        const e = this.enemies[j];
        if (Math.hypot(ox - e.x, oy - e.y) < e.size + 8) {
          e.hp -= 1.5;
          this.particleSystem.emitBurnDash(ox, oy, angle);
          if (e.hp <= 0) {
            this.killEnemy(j);
          }
        }
      }
    }

    // 7. Collect EXP Gems
    const magnetRange = 60;
    for (let i = this.expGems.length - 1; i >= 0; i--) {
      const g = this.expGems[i];
      const dist = Math.hypot(this.px - g.x, this.py - g.y);

      if (dist < magnetRange) {
        // Move towards player
        g.x += ((this.px - g.x) / dist) * 5;
        g.y += ((this.py - g.y) / dist) * 5;

        if (dist < this.playerSize + 6) {
          this.exp += g.value;
          this.expGems.splice(i, 1);
          this.soundManager.playEat();

          if (this.exp >= this.nextExp) {
            this.handleLevelUp();
          } else {
            this.callbacks.onExpChange(this.exp, this.nextExp, this.level);
          }
        }
      }
    }
  }

  private spawnEnemy(): void {
    const side = Math.floor(Math.random() * 4);
    let x = 0;
    let y = 0;

    switch (side) {
      case 0:
        x = Math.random() * this.width;
        y = -20;
        break;
      case 1:
        x = this.width + 20;
        y = Math.random() * this.height;
        break;
      case 2:
        x = Math.random() * this.width;
        y = this.height + 20;
        break;
      case 3:
        x = -20;
        y = Math.random() * this.height;
        break;
    }

    const isFast = Math.random() > 0.6;
    this.enemies.push({
      id: `enemy_${Date.now()}_${Math.random()}`,
      x,
      y,
      hp: isFast ? 15 : 30,
      maxHp: isFast ? 15 : 30,
      speed: isFast ? 1.5 : 0.85,
      size: isFast ? 10 : 14,
      type: isFast ? 'RED_CANDLE' : 'BEAR',
      color: isFast ? '#ff1744' : '#ff5252',
    });
  }

  private fireVenom(): void {
    // Find closest enemy
    let closest: Enemy | null = null;
    let minDist = Infinity;
    for (const e of this.enemies) {
      const d = Math.hypot(this.px - e.x, this.py - e.y);
      if (d < minDist) {
        minDist = d;
        closest = e;
      }
    }

    if (!closest) return;
    const baseAngle = Math.atan2(closest.y - this.py, closest.x - this.px);
    const speed = 7;

    for (let i = 0; i < this.venomCount; i++) {
      const spread = (i - (this.venomCount - 1) / 2) * 0.22;
      const angle = baseAngle + spread;
      this.projectiles.push({
        x: this.px,
        y: this.py,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        damage: 20,
        life: 1500,
      });
    }

    this.soundManager.playBoost();
  }

  private killEnemy(idx: number): void {
    const e = this.enemies[idx];
    this.enemies.splice(idx, 1);
    this.kills++;
    this.callbacks.onKillsChange(this.kills);
    this.particleSystem.emitDeath(e.x, e.y);

    // Drop EXP Gem
    this.expGems.push({
      id: `gem_${Math.random()}`,
      x: e.x,
      y: e.y,
      value: 1,
    });
  }

  private handleLevelUp(): void {
    this.level++;
    this.exp = 0;
    this.nextExp = Math.floor(this.nextExp * 1.5);
    this.soundManager.playHighScore();
    this.callbacks.onExpChange(this.exp, this.nextExp, this.level);

    // 3 Random Upgrades
    const pool: UpgradeChoice[] = [
      { id: 'MULTI_VENOM', title: 'MULTI-VENOM', desc: '毒液發射數量 +1', category: 'WEAPON' },
      { id: 'BURN_AURA', title: 'BURN SHIELD', desc: '增加烈焰旋轉護盾與速度', category: 'WEAPON' },
      { id: 'SLITHER_SPEED', title: 'AGILE SLITHER', desc: '提升移動速度 +20%', category: 'STATS' },
      { id: 'DIAMOND_HANDS', title: 'DIAMOND HANDS', desc: '生命回滿並提高上限 +25', category: 'STATS' },
      { id: 'MEGA_BURN', title: 'MEGA BURN', desc: '全螢幕引爆清除當前所有怪獸', category: 'SPECIAL' },
    ];

    // Pick 3 random
    const shuffled = pool.sort(() => 0.5 - Math.random()).slice(0, 3);
    this.pause();
    this.callbacks.onLevelUp(shuffled);
  }

  private handleGameOver(): void {
    this.isRunning = false;
    this.soundManager.playDie();
    this.particleSystem.emitDeath(this.px, this.py);
    this.callbacks.onGameOver(this.kills, Math.floor(this.elapsedTime), this.level);
  }

  private render(): void {
    const ctx = this.ctx;
    ctx.save();

    // 1. Cyber Dark Background
    ctx.fillStyle = '#0a0e14';
    ctx.fillRect(0, 0, this.width, this.height);

    // 2. Cyber Grid
    ctx.strokeStyle = 'rgba(0, 230, 118, 0.05)';
    ctx.lineWidth = 1;
    for (let x = 0; x < this.width; x += 30) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, this.height);
      ctx.stroke();
    }
    for (let y = 0; y < this.height; y += 30) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(this.width, y);
      ctx.stroke();
    }

    // Border Neon
    ctx.strokeStyle = '#00e676';
    ctx.lineWidth = 2;
    ctx.shadowColor = '#00e676';
    ctx.shadowBlur = 10;
    ctx.strokeRect(1, 1, this.width - 2, this.height - 2);
    ctx.shadowBlur = 0;

    // 3. Render Particles
    this.particleSystem.render(ctx);

    // 4. Render EXP Gems
    for (const g of this.expGems) {
      ctx.fillStyle = '#00e676';
      ctx.shadowColor = '#00e676';
      ctx.shadowBlur = 8;
      ctx.beginPath();
      ctx.arc(g.x, g.y, 4, 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;
    }

    // 5. Render Projectiles (Venom Blasts)
    for (const p of this.projectiles) {
      ctx.fillStyle = '#69f0ae';
      ctx.shadowColor = '#00e676';
      ctx.shadowBlur = 10;
      ctx.beginPath();
      ctx.arc(p.x, p.y, 4.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;
    }

    // 6. Render Orbit Burn Shield
    const orbitRadius = 45;
    for (let o = 0; o < this.orbitCount; o++) {
      const angle = this.orbitAngle + (o * Math.PI * 2) / this.orbitCount;
      const ox = this.px + Math.cos(angle) * orbitRadius;
      const oy = this.py + Math.sin(angle) * orbitRadius;

      ctx.fillStyle = '#ff9100';
      ctx.shadowColor = '#ff3d00';
      ctx.shadowBlur = 14;
      ctx.beginPath();
      ctx.arc(ox, oy, 7, 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;
    }

    // 7. Render Enemies (Bear / Red Candle)
    for (const e of this.enemies) {
      ctx.save();
      ctx.translate(e.x, e.y);

      if (e.type === 'RED_CANDLE') {
        // Red Candlestick
        ctx.fillStyle = '#ff1744';
        ctx.shadowColor = '#ff1744';
        ctx.shadowBlur = 8;
        ctx.fillRect(-e.size / 2, -e.size / 2, e.size, e.size * 1.5);
        ctx.strokeStyle = '#ff8a80';
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(0, -e.size / 2 - 4);
        ctx.lineTo(0, e.size / 2 + 4);
        ctx.stroke();
      } else {
        // Bear Monster
        ctx.fillStyle = '#d50000';
        ctx.beginPath();
        ctx.arc(0, 0, e.size, 0, Math.PI * 2);
        ctx.fill();
        // Ears
        ctx.beginPath();
        ctx.arc(-e.size * 0.7, -e.size * 0.7, e.size * 0.4, 0, Math.PI * 2);
        ctx.arc(e.size * 0.7, -e.size * 0.7, e.size * 0.4, 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.restore();
    }

    // 8. Render Player (SNEK)
    ctx.save();
    ctx.translate(this.px, this.py);

    if (this.invulnerableTimer > 0 && Math.floor(performance.now() / 80) % 2 === 0) {
      ctx.globalAlpha = 0.4;
    }

    if (this.imageLoaded && this.headImage.complete) {
      const s = this.playerSize * 2.2;
      ctx.shadowColor = '#00e676';
      ctx.shadowBlur = 12;
      ctx.drawImage(this.headImage, -s / 2, -s / 2, s, s);
    } else {
      ctx.fillStyle = '#00e676';
      ctx.beginPath();
      ctx.arc(0, 0, this.playerSize, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
    ctx.restore();
  }
}
